from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class DetailStatus(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    status = SchemaField(name='status', not_null=True)
    error_text = SchemaField(name='errorText')

    def __init__(self, id, status, error_text):
        self.id = id
        self.status = status
        self.error_text = error_text

        super(DetailStatus, self).__init__()


class Code(SchemaObject):
    code = SchemaField(name='code', not_null=True)

    def __init__(self, code):
        self.code = code

        super(Code, self).__init__()


class OperationStateRespV1(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    status = SchemaField(name='status', not_null=True)
    links = SchemaField(name='links', many=True)
    detailed_statuses = SchemaField(name='detailedStatuses', klass=DetailStatus, many=True)
    error_message = SchemaField(name='errorMessage')
    error_code = SchemaField(name='errorCode', klass=Code)

    def __init__(self, id, status, links, detailed_statuses, error_message, error_code):
        self.id = id
        self.status = status
        self.links = links
        self.detailed_statuses = detailed_statuses
        self.error_message = error_message
        self.error_code = error_code

        super(OperationStateRespV1, self).__init__()
